def main():
    import sys
    import heapq

    def readints():
        return list(map(int, sys.stdin.readline().split()))

    n, m, k = readints()
    colors = readints()
    paint = [readints() for _ in range(n)]

    # dp[mask][groups] will store the minimum paint used to color the trees represented by mask
    # with exactly 'groups' contiguous groups of the same color.
    dp = [[float('inf')] * (k + 1) for _ in range(1 << n)]
    dp[0][0] = 0

    pq = [(0, 0, 0)]  # (paint_used, mask, groups)

    while pq:
        paint_used, mask, groups = heapq.heappop(pq)

        if dp[mask][groups] < paint_used:
            continue

        for i in range(n):
            if mask & (1 << i):
                continue

            new_mask = mask | (1 << i)

            for j in range(1, m + 1):
                new_paint_used = paint_used + paint[i][j - 1]

