def min_paint(n: int, m: int, k: int, colors: List[int], paint_costs: List[List[int]]) -> int:
    def backtrack(index: int, current_groups: int, current_cost: int) -> bool:
        if index == n:
            return current_groups == k

        if colors[index] != 0:
            return backtrack(index + 1, current_groups + (1 if index == 0 or colors[index] != colors[index - 1] else 0), current_cost)

        min_cost = float('inf')
        for color in range(1, m + 1):
            new_cost = current_cost + paint_costs[index][color - 1]
            if new_cost >= min_cost:
                continue
            colors[index] = color
            if backtrack(index + 1, current_groups + (1 if index == 0 or colors[index] != colors[index - 1] else 0), new_cost):
                min_cost = new_cost
            colors[index] = 0

        return min_cost != float('inf')

    if backtrack(0, 1 if colors[0] == 0 else 0, 0):
        return min_paint.min_cost
    else:
        return -1

